// Mapeo de nombres comunes a entity_ids de Home Assistant
const deviceMap = {
    'luces': 'light.salon',
    'luces del salon': 'light.salon',
    'luces de la cocina': 'light.cocina',
    'luces del cuarto': 'light.dormitorio',
    'television': 'media_player.tv_salon',
    'tv': 'media_player.tv_salon',
    'aire acondicionado': 'climate.aire_salon',
    'aire': 'climate.aire_salon',
    'ventilador': 'fan.ventilador_cuarto',
    'camara': 'camera.entrada',
    'cerradura': 'lock.puerta_principal',
    'persiana': 'cover.persiana_salon',
    'enchufe': 'switch.enchufe_1'
};

const accionMap = {
    'encender': 'turn_on',
    'enciende': 'turn_on',
    'prende': 'turn_on',
    'apagar': 'turn_off',
    'apaga': 'turn_off',
    'reiniciar': 'toggle',
    'abrir': 'open_cover',
    'cerrar': 'close_cover',
    'bloquear': 'lock',
    'desbloquear': 'unlock'
};

const dispositivo = msg.payload.dispositivo || '';
const accion = msg.payload.accion || 'encender';

// Buscar entity_id
const entityId = deviceMap[dispositivo.toLowerCase()] || `light.${dispositivo.replace(/\s+/g, '_')}`;
const haService = accionMap[accion.toLowerCase()] || 'turn_on';

// Determinar dominio desde entity_id
const domain = entityId.split('.')[0];

msg.payload = {
    ...msg.payload,
    entity_id: entityId,
    ha_domain: domain,
    ha_service: haService
};

return msg;

// Mapeo de nombres de escena
const sceneMap = {
    'pelicula': 'scene.modo_pelicula',
    'cine': 'scene.modo_pelicula',
    'noche': 'scene.modo_noche',
    'dormir': 'scene.modo_noche',
    'dia': 'scene.modo_dia',
    'trabajo': 'scene.modo_trabajo',
    'fiesta': 'scene.modo_fiesta',
    'relajacion': 'scene.modo_relajacion',
    'todo apagado': 'scene.todo_apagado',
    'salir': 'scene.salir_de_casa'
};

const escena = msg.payload.tarea || msg.payload.comando || '';
msg.payload.scene_id = sceneMap[escena.toLowerCase()] || `scene.${escena.replace(/\s+/g, '_')}`;

return msg;

msg.payload = {
    mensaje: msg.ha_response || `Comando ejecutado correctamente en Home Assistant.`,
    status: 'ok',
    source: 'node-red + home-assistant',
    timestamp: new Date().toISOString()
};
return msg;

// n8n envia: { entity_id, service, domain, data }
const body = msg.payload;

msg.payload = {
    domain: body.domain || 'light',
    service: body.service || 'turn_on',
    entity_id: body.entity_id || 'light.salon',
    data: body.data || {}
};

return msg;

// Prepara el payload para enviar a n8n
const entityId = msg.data.entity_id;
const state = msg.data.new_state.state;
const friendlyName = msg.data.new_state.attributes.friendly_name || entityId;

msg.payload = {
    event: 'state_changed',
    entity_id: entityId,
    friendly_name: friendlyName,
    new_state: state,
    old_state: msg.data.old_state ? msg.data.old_state.state : 'unknown',
    attributes: msg.data.new_state.attributes,
    timestamp: new Date().toISOString(),
    source: 'home-assistant-via-node-red'
};

return msg;

// Enviar anuncio a Alexa via Voice Monkey
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    token: env.get('VOICE_MONKEY_TOKEN'),
    device: env.get('VOICE_MONKEY_DEVICE'),
    text: msg.announcement || 'Alerta de Home Assistant: ' + (msg.alert_text || 'evento detectado')
};
return msg;
